// Some portions generated by Claude
// Screenshot-shaped fixture, not a reconstruction of private query data.
export function hubNeighborhood(leaves = 75) {
  const nodes = [{id: 'award', label: 'Nobel Prize in Physics', kind: 'iri', x: 0, y: 0}];
  const edges = [];
  const link = (source, target) => edges.push({id: `e${edges.length}`, source, target, predicate: 'urn:related', label: 'related'});
  const names = ['Marie Curie', 'Pierre Curie', 'Albert Einstein', 'Max Planck', 'Irène Joliot-Curie', 'Frédéric Joliot-Curie', 'Paris', 'Warsaw', 'Ulm', 'ETH Zurich', 'University of Paris', 'physics', 'chemistry', 'Nobel Prize in Chemistry', 'France'];
  names.forEach((label, i) => nodes.push({id: `c${i}`, label, kind: 'iri', x: i * 30, y: i * 20}));
  [[0,1],[0,4],[4,5],[0,6],[0,7],[0,10],[0,11],[0,12],[0,13],[1,6],[1,11],[2,8],[2,9],[2,11],[3,11],[4,12],[5,13],[6,14]].forEach(([a,b])=>link(`c${a}`,`c${b}`));
  [0,1,2,3,4].forEach(i=>link(`c${i}`,'award'));
  for(let i=0;i<leaves;i++){nodes.push({id:`leaf${i}`,label:`Q${70000+i}`,kind:'iri',x:0,y:0});link(`leaf${i}`,'award');}
  return {nodes,edges,revision:1};
}
